use strict;
use warnings;
use Test::More;
use DownloadHeaders;

subtest benign_control => sub {
    is(DownloadHeaders::disposition('report.txt'), 'attachment; filename="report.txt"', 'names the file');
};

subtest security_keeps_one_header_line => sub {
    my $value = DownloadHeaders::disposition("report.txt\r\nSet-Cookie: session=x");
    unlike($value, qr/[\r\n]/, 'stays one header line');
};

done_testing();
